// Normaliza a entrada do formulário e guarda o horário de início (para medir o tempo economizado)
const item = $input.first();
const f = item.json;
const binKeys = Object.keys(item.binary || {});
if (!binKeys.length) throw new Error('Nenhum arquivo de áudio recebido.');

const audio = item.binary[binKeys[0]];
const tamanhoMB = Number(audio.fileSize ? String(audio.fileSize).replace(/[^0-9.]/g, '') : 0);
// A API de transcrição aceita até 25 MB. Episódios longos: exporte em MP3 mono 64 kbps (~30 MB/hora → divida em partes)
if (String(audio.fileSize || '').includes('MB') && tamanhoMB > 25) {
  throw new Error(`Áudio com ${tamanhoMB} MB. O limite é 25 MB: exporte em MP3 mono 64 kbps ou divida o episódio.`);
}

return [{
  json: {
    titulo: f['Título do episódio'],
    numero: f['Número do episódio'] ?? '',
    convidados: f['Convidado(s)'] || 'Sem convidados',
    inicio_processamento: new Date().toISOString(),
  },
  binary: { audio },
}];

// Converte os segmentos do Whisper em linhas "[mm:ss] texto"
const seg = $json.segments || [];
const mmss = (s) => {
  const m = Math.floor(s / 60), r = Math.floor(s % 60);
  return `${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}`;
};
const linhas = seg.map(s => `[${mmss(s.start)}] ${s.text.trim()}`);
const ep = $('Preparar entrada').first().json;

return [{
  json: {
    ...ep,
    transcricao_com_timestamps: linhas.length ? linhas.join('\n') : $json.text,
    transcricao_texto: $json.text,
    duracao_segundos: Math.round($json.duration || (seg.at(-1)?.end ?? 0)),
  },
}];

// ✏️ Cole aqui o conteúdo de config/voz-da-marca.md
const VOZ_DA_MARCA = `
[Preencha com o tema, o público e o tom do podcast — veja config/voz-da-marca.md]
`;

// Prompt v1 — mantenha sincronizado com prompts/v1-episodio-para-conteudo.md
const MODELO = 'claude-sonnet-5-5';
const PROMPT_VERSAO = 'v1';

const system = `Você é o editor de conteúdo do podcast "Às Sábias Reflexões".
Sua tarefa é transformar a transcrição de um episódio em materiais de divulgação prontos para revisão humana.

<voz_da_marca>
${VOZ_DA_MARCA.trim()}
</voz_da_marca>

Regras:
1. Use SOMENTE o que está na transcrição. Nunca invente falas, dados, nomes ou histórias.
2. Citações diretas devem ser trechos literais da transcrição.
3. Os timestamps dos cortes devem existir na transcrição (formato [mm:ss] fornecido).
4. Cada corte deve ter entre 30 e 90 segundos e fazer sentido sozinho, sem contexto.
5. Escreva em português do Brasil.
6. Se a transcrição estiver incompleta ou confusa em algum trecho, registre em "alertas_revisao".
7. Responda APENAS com um objeto JSON válido, sem texto antes ou depois, seguindo o esquema.`;

const user = `<episodio>
Título: ${$json.titulo}
Número: ${$json.numero}
Convidado(s): ${$json.convidados}
</episodio>

<transcricao>
${$json.transcricao_com_timestamps}
</transcricao>

Gere o JSON com este esquema:
{
  "resumo_curto": "1 frase (até 160 caracteres) para descrição em plataformas",
  "show_notes": "3 a 5 parágrafos com os principais temas, em ordem",
  "capitulos": [{"inicio": "mm:ss", "titulo": "..."}],
  "cortes": [{"inicio": "mm:ss", "fim": "mm:ss", "gancho": "frase de abertura para o vídeo", "por_que_funciona": "..."}],
  "citacoes": ["trecho literal 1", "trecho literal 2", "trecho literal 3"],
  "post_instagram": "...",
  "post_linkedin": "...",
  "newsletter": {"assunto": "...", "corpo": "..."},
  "alertas_revisao": ["pontos que um humano precisa checar"]
}
Gere de 3 a 5 cortes e de 4 a 8 capítulos.`;

return [{
  json: {
    ...$json,
    prompt_versao: PROMPT_VERSAO,
    requestBody: {
      model: MODELO,
      max_tokens: 8000,
      system,
      messages: [{ role: 'user', content: user }],
    },
  },
}];

// Valida o JSON do Claude, checa os timestamps contra a duração real e monta a linha da planilha
const ep = $('Montar pedido ao Claude').first().json;
const bruto = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
const limpo = bruto.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let out;
try { out = JSON.parse(limpo); }
catch (e) { throw new Error('O Claude não devolveu JSON válido. Início da resposta: ' + bruto.slice(0, 300)); }

const obrigatorios = ['resumo_curto', 'show_notes', 'capitulos', 'cortes', 'citacoes', 'post_instagram', 'post_linkedin', 'newsletter'];
const faltando = obrigatorios.filter(k => out[k] === undefined);
if (faltando.length) throw new Error('Campos ausentes na resposta: ' + faltando.join(', '));

// Checagens automáticas (viram alertas, não bloqueiam)
const alertas = [...(out.alertas_revisao || [])];
const seg = (t) => { const [m, s] = String(t).split(':').map(Number); return m * 60 + s; };
for (const c of out.cortes) {
  const ini = seg(c.inicio), fim = seg(c.fim);
  if (isNaN(ini) || isNaN(fim) || fim <= ini) alertas.push(`Corte com horário inválido: ${c.inicio}–${c.fim}`);
  else if (fim > ep.duracao_segundos + 5) alertas.push(`Corte ${c.inicio}–${c.fim} passa do fim do episódio`);
  else if (fim - ini < 20 || fim - ini > 120) alertas.push(`Corte ${c.inicio}–${c.fim} com duração fora do ideal (${fim - ini}s)`);
}
const textoNormal = ep.transcricao_texto.toLowerCase().replace(/\s+/g, ' ');
for (const q of out.citacoes || []) {
  const trecho = q.toLowerCase().replace(/\s+/g, ' ').replace(/[“”"]/g, '').slice(0, 40);
  if (!textoNormal.includes(trecho)) alertas.push(`Citação não encontrada literalmente na transcrição: "${q.slice(0, 60)}..."`);
}

const segundos = Math.round((Date.now() - new Date(ep.inicio_processamento).getTime()) / 1000);
const fmtLista = (arr, f) => (arr || []).map(f).join('\n');

return [{
  json: {
    'Data': new Date().toISOString().slice(0, 10),
    'Episódio': ep.numero,
    'Título': ep.titulo,
    'Convidados': ep.convidados,
    'Status': 'Aguardando revisão',
    'Resumo curto': out.resumo_curto,
    'Show notes': out.show_notes,
    'Capítulos': fmtLista(out.capitulos, c => `${c.inicio} ${c.titulo}`),
    'Cortes': fmtLista(out.cortes, c => `${c.inicio}–${c.fim} | ${c.gancho} | ${c.por_que_funciona}`),
    'Citações': fmtLista(out.citacoes, q => `• ${q}`),
    'Post Instagram': out.post_instagram,
    'Post LinkedIn': out.post_linkedin,
    'Newsletter - assunto': out.newsletter?.assunto,
    'Newsletter - corpo': out.newsletter?.corpo,
    'Alertas de revisão': alertas.length ? alertas.map(a => `⚠️ ${a}`).join('\n') : 'Nenhum',
    'Duração do episódio (min)': Math.round(ep.duracao_segundos / 60),
    'Tempo de processamento (s)': segundos,
    'Versão do prompt': ep.prompt_versao,
    'Tokens (entrada/saída)': `${$json.usage?.input_tokens ?? '?'} / ${$json.usage?.output_tokens ?? '?'}`,
    'Transcrição': ep.transcricao_com_timestamps.slice(0, 49000),
  },
}];
